#!/usr/bin/env node
'use strict';

// Scrubber commit hook: remove AI co-authorship / "generated by AI" trailers
// from a commit message before the commit closes, while keeping human
// co-authors. Invoked from a prepare-commit-msg git hook with the commit
// message file as argv[2]. Fail-open: any error leaves the message untouched.

const fs = require('node:fs');
const { stripAiCoauthorship } = require('../lib/scrubber/coauthor-strip');

function run(message) {
  return stripAiCoauthorship(message);
}

function main(argv) {
  if (/^(1|true|yes)$/i.test(String(process.env.EGC_SKIP_PRECOMMIT || process.env.EGC_SKIP_GIT_HOOKS || ''))) {
    return 0;
  }
  const file = argv[2];
  if (!file) return 0;

  let text;
  try {
    text = fs.readFileSync(file, 'utf8');
  } catch {
    return 0;
  }

  let result;
  try {
    result = run(text);
  } catch {
    return 0;
  }

  if (result.removed.length > 0) {
    try {
      fs.writeFileSync(file, result.message);
      process.stderr.write(`[scrubber] removed ${result.removed.length} AI attribution line(s) from the commit message\n`);
    } catch {
      return 0;
    }
  }
  return 0;
}

if (require.main === module) {
  process.exit(main(process.argv));
}

module.exports = { run, main };
